# Generated by baroo backstage for {{TAP_LABEL}}: save it to the Pico as config.py.
# Holds the wifi password and the tap's token, keep it to yourself. Changed in backstage,
# it takes effect only once authorized and saved to the Pico again.

WIFI_SSID = {{WIFI_SSID}}
WIFI_PASSWORD = {{WIFI_PASSWORD}}
# Two-letter country code; it decides which wifi channels the radio may use.
WIFI_COUNTRY = {{WIFI_COUNTRY}}

# Where baroo runs, by IP address — MicroPython cannot resolve .local names.
SERVER = {{SERVER}}

# The bar's slug, as in /bar/<slug>.
BAR = {{BAR}}

# Who this TapTapper is to baroo. Valid through {{TOKEN_VALID_THROUGH}}.
TAP_TOKEN = {{TAP_TOKEN}}

# Optional buzzer module. None = signal on the on-board LED only.
BUZZER_PIN = {{BUZZER_PIN}}
# Some 3-pin buzzer modules sound while their input is LOW.
BUZZER_ACTIVE_LOW = {{BUZZER_ACTIVE_LOW}}

# A 2.8" ILI9341 display on SPI1 (README.md, "Display"). False for a TapTapper without one.
DISPLAY = {{DISPLAY}}
# How the panel is driven: 0x48 suits most of these modules. Red and blue swapped: 0x40.
# Upside down: 0x88. Mirrored: 0x08.
DISPLAY_MADCTL = {{DISPLAY_MADCTL}}

# Size buttons left to right (README.md, "Size buttons"): the GPIO pin of each and its color
# They serve the sizes the drink on tap is offered in, in order.
BUTTONS = {{BUTTONS}}

# Reboots the TapTapper if it ever hangs. Set to False while working in Thonny: once
# started the watchdog cannot be stopped, and it would reboot the Pico under the REPL.
WATCHDOG = {{WATCHDOG}}
